    "4716": "インストールプロセス中にエラーが発生し、必要なファイルが見つからない場合、AI サービスがクラッシュまたは機能低下する可能性があります。",
    "4717": "提案：",
    "4719": "インストールディレクトリに書き込み権限があるか確認する",
    "4720": "問題が解決しない場合は、アプリをアンインストールして再インストールしてください",
    "4721": "知っていた",
    "4740": "最小単位認識がオフになっています",
    "4741": "最小単位の認識を有効にする",
    "4742": "有効にすると、ディレクトリが最小単位として識別され、ファイルがスキップされて 1 つずつ分析されます。",
    "4744": "オーディオ アルバム: 同じアルバムのオーディオ トラック ファイルのコレクション (.flac、.mp3 など)",
    "4745": "シリーズ ファイル: 連続番号が付けられた文書または写真 (01.jpg、02.jpg、03.jpg など)",
    "4747": "ヒント: 閉じた後、すべてのファイルは個別に分析されます。これは、ファイルごとに説明とラベルを個別に生成する必要があるシナリオに適しています。",
