    "6227": "ファイルはAI分析により分類されるため、多すぎると時間がかかります。動作モードによって、分析結果をサーバーにキャッシュするかどうかが決まります。",
    "6229": "ダウンロードディレクトリ、ネットワークリソース、電子書籍、漫画、音楽などの公開ファイル。",
    "6230": "あなたの分析結果はローカルにのみ保存され、サーバーにはキャッシュされません。データ主権を守ります。ただし、サーバーキャッシュによる高速化効果は得られません。",
    "6231": "個人のオリジナル作品、写真、財務諸表、プライバシードキュメント。",
    "6234": "すでに整理されています。分析をスキップします。強制的に分析する場合は、独立した作業ディレクトリを作成してください。",
