    "7685": "常にプライバシー保護を中心的な設計原則として考慮し、次の事項を遵守してください。",
    "7686": "データローカル優先度",
    "7687": "、ユーザーのプライバシーとセキュリティを効果的に保護するためのものであり、その中心となる技術原則は業界の一般的なハッシュ (Hash) メカニズムと論理的に一致しています。",
    "7688": "簡単に言うと",
    "7689": "の場合、システムは暗号化アルゴリズムを通じてファイルごとに一意の特性識別子 (長さ 16 ～ 128 文字) を生成します。これはファイルの一意の ID に相当します。",
    "7690": "このIDを生成します",
    "7691": "唯一の前提",
    "7692": "、ユーザーはファイルをローカルに保持し、アルゴリズムの計算を完了します。アプリケーションはファイルIDを第三者に開示することはありません。このIDでのみ、該当IDの解析データをサーバーに要求することができ、それ以外に取得する方法はありません。",
    "7693": "中でも",
    "7694": "極端な仮定のもとでは",
    "7695": "（サーバーが侵害された）、サードパーティはファイル分析データと対応するIDのみを取得でき、異なるプラットフォームのIDアルゴリズムは完全に独立しており、Baidu NetdiskなどのプラットフォームのファイルIDとは関係がなく、プラットフォーム間で元のファイルを照合することはできません。",
    "7696": "同時に、",
    "7697": "サーバーには分析データのみが保存されます",
    "7698": ": スマート ファイル名、タグ、コンテンツの概要、評価と理由、メタデータなどが含まれます。これらは右側のプロパティ パネルに表示されます。ファイル自体がアップロードまたは保存されることはありません。",
