    "7849": "スイッチ",
    "7850": "これをオンにすると、ローカル モデルとクラウド モデルは思考モードを開始できるようになり、AI 分析の品質が向上する可能性がありますが、応答時間が大幅に増加します。",
    "7874": "分析キュー",
    "7875": "AIモデルの保存場所を選択します",
    "7876": "AI モデルは、ソフトウェアにインテリジェントな分析機能を持たせるためのコア ファイルであり、サイズが大きくなります。",
    "7877": "モデルの保存パス",
    "7878": "親切なヒント",
    "7879": "モデルによっては、2 ～ 8GB、またはそれ以上のスペースを占有する場合があります。十分な空き容量のあるディスクを選択することをお勧めします。",
    "7880": "SSD (ソリッド ステート ドライブ) を優先すると、より高速なモデルの読み込みとスムーズな AI 分析が可能になります。",
    "7881": "空のフォルダーを選択するか、新しいフォルダーを作成するだけで、既存のファイルには影響しません。",
    "7883": "OCR認識精度",
    "7884": "OCR テキスト認識の精度レベルを選択します。非常に高速な OCR は、ほとんどのシナリオに適しています。高精度 OCR 認識はより正確ですが、少し時間がかかります。",
    "7885": "非常に高速な OCR",
    "7887": "高精細OCR",
    "7889": "再分析時にデータを再利用する",
    "7890": "ファイルが更新されている場合は、この項目をオフにしてください。また、既にファイルの基本情報が存在する場合には、この情報の取得をスキップします。基本情報には、ファイル タイプ、サムネイル、メタデータ、ファイル コンテンツが含まれます。",
    "7891": "分析が高速化され、単純な分類段階の情報が再取得されることはありません。",
    "7892": "プラグインのインストール: LibreOffice",
    "7895": "Windows インストール チュートリアルを非表示にする 💡",
    "7896": "Windows のインストールと PATH 構成のチュートリアルを展開します 💡",
    "7897": "設定方法:",
    "7898": "まず、LibreOffice のインストール パスをシステムの PATH 環境変数に追加してください。",
    "7899": "デフォルトの場所:",
    "7900": "モデルを切り替えています。お待ちください",
    "7901": "元のファイルがディスク上で紛失したか、移動されました",
    "7902": "紛失しました",
    "7903": "構成後、アプリケーションを再起動し、再度「再検出」をクリックします。",
    "7905": "次のカテゴリは強制的に識別されるため、オンにする必要はありません: システム ディレクトリ、ソフトウェア インストール ディレクトリ、エンジニアリング プロジェクト、ゲーム パッケージ、AI データ セット/モデル、キャッシュと LFS、仮想環境",
    "7906": "デザイン プロジェクト: プロジェクト ファイルとリソース ディレクトリ (.prproj、.aep、.blend など) を含むデザイン プロジェクト",
    "7907": "高度な AI プロンプトワードのカスタマイズ",
    "7908": "プロンプトの単語をカスタマイズしてモデルを微調整してカテゴリに名前を付け、品質をスコア付けし、より適切に従うクラウド モデルを推奨します。",
    "7909": "単語数が多すぎてAI解析に失敗する場合は、ご自身で単語数を減らしてください。ローカルの小規模モデルの場合は、100 ワード以内にすることをお勧めします。",
    "7910": "最小単位識別プロンプト ワード (最小単位識別を有効にする必要があります)",
