    "9748": "シリコンベースのフロー",
    "9749": "さまざまな主流のオープンソース モデルに高速推論インターフェイスを提供し、10B 未満の一部のモデルは長期間無料です。",
    "9750": "シリコンベースのフローのフルモーダル処理モデル",
    "9753": "マジックコミュニティ",
    "9754": "Alibaba のオープンソース モデル コミュニティは、無料のモデル推論 API を提供します (モデルは 500 回の呼び出しごとに置き換える必要があります)。",
    "9755": "Modaコミュニティの視覚言語処理モデル",
    "9756": "Moda Communityのテキスト処理モデル",
    "9757": "DeepSeek 公式インターフェースは、コスト効率の高い DeepSeek-V3/R1 シリーズ モデルを提供します。",
    "9759": "Deepseek の最上位推論モデル",
    "9761": "Deepseek のまばらな注意モデル",
