    "9765": "ムーンショット v1 自動",
    "9766": "キミの最適化バージョンモデル",
    "9767": "ウィズダムスペクトルAI",
    "9768": "清華大学 AI 研究室出身。強力な国内大型モデル サービスの GLM シリーズを提供。",
    "9769": "Zhipu AI のエンタープライズレベルのテキスト処理モデル",
    "9770": "Zhipu AIの視覚推論モデル",
    "9771": "大規模なモデル サービスをローカルで実行するためのもう 1 つの外部ソリューションです。これは、Firefly の組み込み AI エンジンより 20 ～ 40% 遅いですが、ハードウェアの互換性が高く、インストールすることをお勧めします。",
    "9772": "NVIDIA が提供するモデル エクスペリエンス プラットフォームは、さまざまな主流の大規模モデルをホストしており、現在無料トライアルを提供しています。",
    "9774": "NVIDIA がホストする Tongyi Qianwen 3 コード モデル",
    "9777": "NVIDIA 軽量ビジュアル言語モデル",
    "9779": "Microsoft のマルチモーダル命令モデル",
    "9781": "Google の Gemma 3 命令微調整モデル",
    "9784": "センスタイム",
    "9785": "SenseTime の毎日の新しい大型モデル インターフェイスは現在パブリック ベータ期間中であり、無料の通話割り当てを提供します。",
    "9787": "SenseTimeの高性能軽量モデル",
    "9789": "SenseTime の非常に高速な推論モデル",
    "9792": "SenseTime がホストする DeepSeek 高速推論モデル",
    "9794": "サインアップすると 10 ドルの試用版を入手できます。クレジット カードは必要ありません。クレジットの有効期限は 3 か月以内です。 Jamba Large モデルと Jamba Mini モデルが含まれます。",
    "9795": "イスラエル",
    "9800": "Alibaba Cloud Bailian（国際版）",
    "9801": "登録後、Tongyi Qianwen の各モデルは、90 日間有効な 100 万個の無料トークンを受け取ります (国際線/シンガポール エリア)。クレジットカードは必要ありません。",
    "9803": "無料の「トライアル」API キー。クレジット カードは必要ありません。 1 か月あたり 1000 回の API 呼び出し。非営利使用のみ。",
    "9804": "カナダ",
    "9816": "無料の「実験的」プラン、クレジット カードは必要ありません。毎月約 10 億トークン。モデルを改善するために手がかりとなる言葉が使用される場合があります。",
    "9825": "志浦AI",
    "9826": "永久無料モデルを提供しており、クレジット カードは必要ありません。",
    "9829": "無料、クレジットカードは必要ありません。非常に高速な推論 (約 2600 トークン/秒)。 1 日あたりの制限は 100 万トークンです。無料ファイル 8K コンテキスト制限。 llama3.1-8b は 2026 年 5 月 27 日に非推奨になる予定です。",
    "9835": "毎日 10,000 個のニューロンが無料。無料版では50以上のモデルが提供されています。",
    "9841": "すべての GitHub ユーザーに無料のプロトタイピング クレジットを提供します。 45以上のモデルが含まれています。 1 回のリクエストには制限があります (8K 入力 / 4K 出力)。",
    "9846": "無料、クレジットカードは必要ありません。非常に高速な LPU 推論。",
    "9851": "無料ユーザーに月間 100,000 回の推論サービス割り当てを提供します。 Fireworks、Togetter、Hyperbolic、Nebius、Novita、DeepInfra などのプロバイダーへのルート。数千のモデルをサポートします。",
    "9855": "無料モデル、クレジットカードは不要です。 `kilo-auto/free` は自動的に minimax/minimax-m2.5:free (80%) および stepfun/step-3.5-flash:free (20%) にルーティングされます。",
    "9857": "シームレスな API ゲートウェイ。基本的なアクセスには登録は必要ありません。 30以上のモデルをサポートします。 GDPR準拠。",
    "9858": "イギリス",
    "9862": "モデルスコープ",
    "9863": "登録ユーザーに無料の API 推論サービスを提供します。 Alibaba Cloud アカウントをバインドし、実名認証を完了する必要があります。",
    "9868": "サインアップすると 1 ドルの無料クレジットを獲得できます。クレジット カードは必要ありません。 OpenAI 互換 API を通じて 60 を超えるオープン ソース モデルを利用できます。本社はEUにあります。",
    "9869": "オランダ",
    "9872": "サインアップすると、5 ドル分の無料クレジットを獲得できます。クレジット カードは必要ありません。ノルウェーにデータセンターを置く EU の主権プロバイダー。レート制限もコールドスタートもありません。",
    "9874": "質的使用制限付きで無料。 Ollama ライブラリから 400 以上のモデルを提供します。 OpenAI SDK と互換性がないため、[Ollama API](https://docs.ollama.com/cloud) を使用してください。",
    "9877": "OVHクラウドAIターミナル",
    "9878": "無料の匿名プロファイル (API キーなし、登録不要): IP ごとにモデルごとに 2 RPM に制限されます。 EU 内で 40 を超えるオープンソースの重みモデルをホストしています。 OpenAI SDKと互換性があります。",
    "9882": "無料の毎日のトークン割り当て、クレジット カードは必要ありません。ロールプレイングやストーリー作成用に設計されています。",
    "9885": "1 分あたりのリクエスト数は 20 に制限されています。リクエストが短期間に速すぎる場合は、頻度制限がトリガーされます (1 分待ってから再試行する必要があります)。",
    "9886": "シンガポール",
